	/** 
	 * jumpstart the process by instantiating2 Goal
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		goalId = GoalService.getGoalInstance()
		.createGoal( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		GoalService.getGoalInstance()
				.createGoal( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.goalSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Goal : " + successValue.getGoalId());
							  if (successValue.getGoalId().equals(goalId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfGoalList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Goal test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on goal consumed")
					);
			subscriber.goalSubscribe( goalId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Goal : " + successValue.getGoalId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfGoalList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on goal for goalId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Goal. 
	 */
	protected Goal read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Goal" );

		Goal entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Goal with primary key" );
		msg.append( goalId );
		
		GoalFetchOneSummary fetchOneSummary = new GoalFetchOneSummary( goalId );

		try {
			entity = GoalService.getGoalInstance().getGoal( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Goal " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Goal.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Goal." );

		StringBuilder msg = new StringBuilder( "Failed to update a Goal : " );        
		Goal entity = read();
		UpdateGoalCommand command = generateUpdateCommand();
		command.setGoalId(entity.getGoalId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Goal." );

			// for use later on...
			goalId = entity.getGoalId();

			GoalService proxy = GoalService.getGoalInstance();  

			proxy.updateGoal( command ).get();

			LOGGER.info( "-- Successfully saved Goal - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + goalId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Goal.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Goal." );

		Goal entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Goal with id " + goalId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Goal with id " + goalId );

			throw e;
		}

		try{
			GoalService.getGoalInstance().delete( new DeleteGoalCommand( entity.getGoalId() ) ).get();
			LOGGER.info( "-- Successfully deleted Goal with id " + goalId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Goal with id " + goalId );

			throw e;
		}
	}

	/**
	 * get all Goals.
	 */
	protected List<Goal> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Goals:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Goal : " );        
		List<Goal> collection  = new ArrayList<>();

		try {
			// call the static get method on the GoalService
			collection = GoalService.getGoalInstance().getAllGoal();
			assertNotNull( collection, "An Empty collection of Goal was incorrectly returned.");
			
			// Now print out the values
			Goal entity = null;            
			Iterator<Goal> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getGoalId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

